import { api } from "@/lib/api";

import type {
  ExecutiveReport,
  GenerateReportPayload,
  GenerateReportResponse,
  ReportsResponse,
} from "@/types/report.types";

class ReportService {
  /**
   * Returns every report generated by the current user.
   */
  async getReports(): Promise<ReportsResponse> {
    const { data } =
      await api.get<ReportsResponse>(
        "/reports",
      );

    return data;
  }

  /**
   * Starts a new Executive Report generation.
   */
  async generateReport(
    payload: GenerateReportPayload,
  ): Promise<GenerateReportResponse> {
    const { data } =
      await api.post<GenerateReportResponse>(
        "/reports/generate",
        payload,
      );

    return data;
  }

  /**
   * Returns a single report.
   */
  async getReport(
    reportId: string,
  ): Promise<ExecutiveReport> {
    const { data } =
      await api.get<ExecutiveReport>(
        `/reports/${reportId}`,
      );

    return data;
  }

  /**
   * Deletes a generated report.
   */
  async deleteReport(
    userId: string,
    reportId: string,
  ) {
    return api.delete(
      `/users/${userId}/reports/${reportId}`,
    );
  }

  /**
   * Downloads the PDF report.
   */
  async downloadPdf(
    userId: string,
    reportId: string,
  ) {
    return api.get(
      `/users/${userId}/reports/${reportId}/download/pdf`,
      {
        responseType: "blob",
      },
    );
  }

  /**
   * Downloads the CSV report.
   */
  async downloadCsv(
    userId: string,
    reportId: string,
  ) {
    return api.get(
      `/users/${userId}/reports/${reportId}/download/csv`,
      {
        responseType: "blob",
      },
    );
  }
}

export const reportService =
  new ReportService();